    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: { position: 'right', labels: { color: '#464E5F', font: { size: 12 } } },
        tooltip: { callbacks: { label: (ctx) => `${ctx.label}: ${fmtRp(ctx.raw)}` } },
