  // 3. Theoretical vs Actual Cost Gap
  const monthsMap = {};
  pnlMonthly.forEach((r) => {
    if (state.selectedOutlet !== 'ALL' && r.outlet_id !== state.selectedOutlet) return;
    const m = r.report_month;
