/* ==========================================================================
   Nge-Meal. - Modern F&B Multi-Outlet Analytics & Cost Control Dashboard
   Color Palette & Theme inspired by Nge-Meal Food Delivery Admin
   ========================================================================== */

:root {
  /* Brand Theme Tokens */
  --bg-app: #F8F9FD;
  --bg-card: #FFFFFF;
  --bg-card-hover: #FFFFFF;
  --bg-sidebar: #FFFFFF;
  --bg-input: #F8F9FD;

  /* Primary & Accent Colors */
  --brand-yellow: #F8B602;
  --brand-yellow-hover: #E5A700;
  --brand-yellow-light: #FFF9E6;
  --brand-yellow-glow: 0 6px 20px rgba(248, 182, 2, 0.35);

  --brand-orange: #FA8B0C;
  --brand-gradient: linear-gradient(135deg, #F8B602 0%, #FA8B0C 100%);
  --brand-gradient-subtle: linear-gradient(135deg, #FFF9E6 0%, #FFF2D1 100%);

  /* Status & Semantic Colors */
  --color-coral: #FF5B5B;
  --color-coral-light: #FFF0F0;
  --color-green: #00B074;
  --color-green-light: #E8F9F1;
  --color-blue: #2F80ED;
  --color-blue-light: #EEF6FF;
  --color-purple: #8950FC;
  --color-purple-light: #F3E8FF;

  /* Text Colors */
  --text-title: #1C1D21;
  --text-body: #464E5F;
  --text-muted: #8F92A1;
  --text-light: #B5B5C3;

  /* Borders & Shadows */
  --border-light: #EFF0F6;
  --border-focus: #F8B602;
  --shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.03);
  --shadow-card: 0 6px 24px rgba(149, 157, 165, 0.06), 0 1px 3px rgba(0, 0, 0, 0.02);
  --shadow-hover: 0 12px 32px rgba(149, 157, 165, 0.12);

  /* Geometry */
  --radius-sm: 10px;
  --radius-md: 16px;
  --radius-lg: 20px;
  --radius-pill: 9999px;
  --transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
  --font-sans: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

html {
  zoom: 0.9;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg-app);
  color: var(--text-body);
  line-height: 1.5;
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
}

/* ==========================================================================
   Dashboard Shell & Layout
   ========================================================================== */
.dashboard-layout {
  display: flex;
  min-height: 100vh;
  background-color: var(--bg-app);
}

/* ==========================================================================
   Sidebar Navigation & Control Center
   ========================================================================== */
.dashboard-sidebar {
  width: 290px;
  min-width: 290px;
  background: #FFFFFF;
  border-right: 1px solid var(--border-light);
  height: 100vh;
  position: sticky;
  top: 0;
  display: flex;
  flex-direction: column;
  z-index: 100;
  box-shadow: 1px 0 10px rgba(0, 0, 0, 0.02);
  transition: width 0.28s cubic-bezier(0.16, 1, 0.3, 1), min-width 0.28s cubic-bezier(0.16, 1, 0.3, 1);
}

/* Collapsed / Minimalist State */
.dashboard-sidebar.collapsed {
  width: 70px;
  min-width: 70px;
}

/* Sidebar Header */
.sidebar-header {
  padding: 10px 14px;
  border-bottom: 1px solid var(--border-light);
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 52px;
  box-sizing: border-box;
  flex-shrink: 0;
}

.sidebar-brand-wrapper {
  display: flex;
  align-items: center;
  gap: 8px;
  overflow: hidden;
}

.brand-logo-icon {
  width: 32px;
  height: 32px;
  min-width: 32px;
  border-radius: 8px;
  background: var(--brand-gradient);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #FFFFFF;
  box-shadow: var(--brand-yellow-glow);
}

.brand-logo-icon svg {
  width: 18px;
  height: 18px;
  stroke: #FFFFFF;
}

.sidebar-brand-text {
  display: flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
}

.dashboard-sidebar.collapsed .sidebar-brand-text {
  display: none;
}

.brand-title {
  font-size: 19px;
  font-weight: 800;
  letter-spacing: -0.03em;
  color: var(--text-title);
  line-height: 1;
}

.brand-title .brand-dot {
  color: var(--brand-yellow);
}

.brand-badge {
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 2.5px 6px;
  border-radius: var(--radius-pill);
  background: var(--brand-yellow-light);
  color: #B47D00;
}

.btn-toggle-sidebar {
  width: 30px;
  height: 30px;
  border-radius: 8px;
  background: var(--bg-input);
  border: 1px solid var(--border-light);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  color: var(--text-muted);
  transition: var(--transition);
  padding: 0;
  flex-shrink: 0;
}

.btn-toggle-sidebar:hover {
  background: var(--brand-yellow-light);
  color: var(--text-title);
  border-color: rgba(248, 182, 2, 0.4);
}

.toggle-icon-svg {
  width: 15px;
  height: 15px;
  transition: transform 0.25s ease;
}

.dashboard-sidebar.collapsed .sidebar-header .btn-toggle-sidebar .toggle-icon-svg {
  transform: rotate(180deg);
}

.dashboard-sidebar.collapsed .sidebar-header {
  padding: 16px 10px;
  justify-content: center;
  flex-direction: column;
  gap: 10px;
}

/* Sidebar Body */
.sidebar-body {
  flex: 1 1 auto;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  scrollbar-width: thin;
  min-height: 0;
}

.sidebar-body::-webkit-scrollbar {
  width: 4px;
}
.sidebar-body::-webkit-scrollbar-thumb {
  background: var(--border-light);
  border-radius: 4px;
}

/* Hero Mini Card */
.sidebar-hero-card {
  background: var(--brand-gradient);
  border-radius: 10px;
  padding: 8px 10px;
  color: #FFFFFF;
  position: relative;
  overflow: hidden;
  box-shadow: 0 4px 14px rgba(248, 182, 2, 0.25);
  transition: all 0.25s ease;
  flex-shrink: 0;
}

.dashboard-sidebar.collapsed .sidebar-hero-card {
  display: none;
}

.sidebar-hero-card h3 {
  font-size: 12px;
  font-weight: 800;
  letter-spacing: -0.01em;
  margin-bottom: 1px;
}

.sidebar-hero-card p {
  font-size: 10px;
  opacity: 0.92;
  font-weight: 500;
  line-height: 1.25;
}

/* Sidebar Sections */
.sidebar-section {
  display: flex;
  flex-direction: column;
  gap: 5px;
  flex-shrink: 0;
}

.sidebar-section-title {
  font-size: 9.5px;
  font-weight: 800;
  letter-spacing: 0.04em;
  color: var(--text-muted);
  text-transform: uppercase;
  display: flex;
  align-items: center;
  gap: 5px;
  margin-bottom: 1px;
}

.section-icon-svg {
  width: 12px;
  height: 12px;
  stroke: var(--brand-yellow);
}

.dashboard-sidebar.collapsed .sidebar-section-title {
  display: none;
}

.sidebar-control-group {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.dashboard-sidebar.collapsed .sidebar-control-group {
  display: none;
}

.sidebar-label {
  font-size: 10.5px;
  font-weight: 700;
  color: var(--text-title);
}

.sidebar-select {
  background: var(--bg-input);
  border: 1px solid var(--border-light);
  border-radius: 6px;
  color: var(--text-title);
  font-size: 11.5px;
  font-weight: 600;
  padding: 4.5px 8px;
  outline: none;
  cursor: pointer;
  transition: var(--transition);
  width: 100%;
}

.sidebar-select:focus {
  border-color: var(--brand-yellow);
  background: #FFFFFF;
  box-shadow: 0 0 0 3px rgba(248, 182, 2, 0.15);
}

.sidebar-date-inputs {
  display: flex;
  align-items: center;
  gap: 4px;
}

.sidebar-input-date {
  background: var(--bg-input);
  border: 1px solid var(--border-light);
  border-radius: 6px;
  color: var(--text-title);
  font-family: inherit;
  font-size: 10.5px;
  font-weight: 600;
  padding: 3.5px 6px;
  outline: none;
  cursor: pointer;
  width: 100%;
  transition: var(--transition);
}

