  gap: 6px;
}

.sidebar-meta-link {
  flex: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  font-size: 11px;
  font-weight: 700;
  padding: 5px 8px;
  border-radius: var(--radius-sm);
  background: #FFF9F2;
  border: 1px solid rgba(250, 139, 12, 0.22);
  color: #D96B00;
  text-decoration: none;
  transition: var(--transition);
}

.sidebar-meta-link svg {
  stroke: #D96B00;
  transition: var(--transition);
}

.sidebar-meta-link:hover {
  background: var(--brand-gradient);
  border-color: #FA8B0C;
  color: #FFFFFF;
  box-shadow: 0 4px 12px rgba(250, 139, 12, 0.25);
  transform: translateY(-1px);
}

.sidebar-meta-link:hover svg {
  stroke: #FFFFFF;
}

/* ==========================================================================
   Main Dashboard Area & Header
   ========================================================================== */
.dashboard-main-area {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  background-color: var(--bg-app);
}

.main-header {
  position: sticky;
  top: 0;
  z-index: 80;
  background: rgba(246, 247, 251, 0.95);
  backdrop-filter: blur(12px);
  padding: 10px 24px;
  border-bottom: 1px solid rgba(239, 240, 246, 0.85);
  display: flex;
  align-items: center;
  gap: 10px;
}

.topbar-toggle {
  display: none;
  flex-shrink: 0;
}

.dashboard-sidebar.collapsed ~ .dashboard-main-area .topbar-toggle {
  display: flex;
}

.dashboard-content {
  padding: 20px 28px 48px;
  flex: 1;
}

/* ==========================================================================
   Navigation Tabs (Clean Pill Style, No Emojis, Fully Adaptive)
   ========================================================================== */
.nav-tabs {
  display: flex;
  flex: 1 1 auto;
  width: 100%;
  gap: 6px;
  background: var(--bg-card);
  padding: 4px 6px;
  border-radius: var(--radius-pill);
  border: 1px solid var(--border-light);
  box-shadow: var(--shadow-sm);
  margin-bottom: 0;
  overflow-x: auto;
  overflow-y: hidden;
  white-space: nowrap;
  flex-wrap: nowrap;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}

.nav-tabs::-webkit-scrollbar {
  display: none;
}

.tab-btn {
  flex: 0 0 auto;
  min-width: max-content;
  background: transparent;
  border: none;
  color: var(--text-muted);
  font-family: inherit;
  font-size: 13px;
  font-weight: 700;
  padding: 7px 14px;
  border-radius: var(--radius-pill);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  transition: var(--transition);
  white-space: nowrap;
}

.tab-btn:hover {
  color: var(--text-title);
  background: var(--brand-yellow-light);
}

.tab-btn.active {
  background: var(--brand-yellow);
  color: var(--text-title);
