}

/* ==========================================================================
   KPI Cards Grid (Compact Single-Row Values, No Wrap)
   ========================================================================== */
.kpi-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
  margin-bottom: 22px;
}

@media (min-width: 1800px) {
