/* ==========================================================================
   Panels, Cards & Charts Layout
   ========================================================================== */
.chart-panel-row {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 460px), 1fr));
  gap: 20px;
  margin-bottom: 22px;
