}

.panel-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 18px;
  flex-wrap: wrap;
  gap: 10px;
}

.panel-title {
  font-size: 16px;
  font-weight: 800;
  letter-spacing: -0.01em;
