  color: var(--color-blue);
  border: 1px solid rgba(47, 128, 237, 0.3);
}

.badge-puzzle {
  background: var(--color-purple-light);
  color: var(--color-purple);
  border: 1px solid rgba(137, 80, 252, 0.3);
}

.badge-dog {
