}

/* ==========================================================================
   Alert Boxes
   ========================================================================== */
.alert-box {
  background: var(--color-coral-light);
  border: 1px solid rgba(255, 91, 91, 0.25);
  border-radius: var(--radius-md);
  padding: 14px 18px;
