  font-weight: 800;
  color: var(--text-title);
  margin-bottom: 2px;
}

.alert-content p {
  font-size: 13px;
  font-weight: 500;
  color: var(--text-body);
}

/* ==========================================================================
   Simulator Controls
   ========================================================================== */
.simulator-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 18px;
  margin-bottom: 22px;
}

.slider-group {
  background: var(--bg-input);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  padding: 16px 18px;
}

.slider-header {
  display: flex;
  justify-content: space-between;
  margin-bottom: 8px;
  font-size: 13px;
  font-weight: 700;
  color: var(--text-title);
}

.slider-val {
  color: var(--brand-yellow);
  font-weight: 800;
}

input[type="range"] {
  width: 100%;
  accent-color: var(--brand-yellow);
  cursor: pointer;
}

/* ==========================================================================
   Heatmap (Golden Warm Tone)
   ========================================================================== */
.heatmap-container {
  display: grid;
  grid-template-columns: 80px repeat(24, 1fr);
  gap: 4px;
  font-size: 11px;
  text-align: center;
  overflow-x: auto;
  padding: 12px 0;
}

.heatmap-cell {
  height: 30px;
