/* ==========================================================================
   Tab Visibility & Animations
   ========================================================================== */
.tab-section {
  display: none;
}

.tab-section.active {
  display: block;
  animation: fadeIn 0.25s cubic-bezier(0.16, 1, 0.3, 1);
